#ifndef PACKAGE_CHASSIS_H
#define PACKAGE_CHASSIS_H
// BT2018-FIRST-CLASS P3/P7: package-registered chassis.
//
// A mounted mod with the "package_chassis" capability ships one
// data/defs/chassis/<ns>/<family>/chassisdef.fit per chassis (generated by
// tools/bt2018_mechs/compile.py). The file is BOTH the object type the mission
// loads (ObjectClass/ObjectType/MechProfile, exactly the blocks an Object2.pak
// packet holds) AND the registry record: qualified chassis id, mech-lab grid
// regions per body location, BT weapon mounts with their weapon-node sockets,
// and the mass budget. Stock chassis never appear here, so stock registration
// order, object-type numbers and every legacy rule stay untouched.
//
// This header is PURE (std only): allocation of runtime object-type numbers and
// the mount/region/mass legality rules, so the same rules serve the mech lab
// (LogisticsVariant::canAddComponent), deployment (mount assignment handed to
// BattleMech) and the offline doctest tier (tests/unit/test_package_chassis.cpp).
// The engine half (enumerate + parse + lookups) lives in package_chassis_registry.cpp.

#include <string>
#include <string_view>
#include <vector>
#include <cstdint>
#include <optional>

namespace mc2pkg {

// ObjectTypeManager's table is 4096 slots and its last five are the misc-terrain handles
// (objtype.cpp); package object-type numbers stay below them.
inline constexpr long kPackageTypeLimit = 4096 - 5;

enum class Mount : int { Energy = 0, Ballistic = 1, Missile = 2, AntiPersonnel = 3, None = -1 };

inline Mount mountFromName(std::string_view s) {
    if (s == "Energy") return Mount::Energy;
    if (s == "Ballistic") return Mount::Ballistic;
    if (s == "Missile") return Mount::Missile;
    if (s == "AntiPersonnel") return Mount::AntiPersonnel;
    return Mount::None;
}

inline const char* mountName(Mount m) {
    switch (m) {
        case Mount::Energy: return "Energy";
        case Mount::Ballistic: return "Ballistic";
        case Mount::Missile: return "Missile";
        case Mount::AntiPersonnel: return "AntiPersonnel";
        default: return "None";
    }
}

// FNV-1a of the hardpoint id string; the same hash code/hardpoint.h uses for HardpointId.
inline unsigned int hardpointKey(std::string_view id) {
    if (id.empty()) return 0u;
    unsigned int h = 2166136261u;
    for (char c : id) { h ^= static_cast<unsigned char>(c); h *= 16777619u; }
    return h;
}

struct Region {
    std::string location;   // BT location name (LeftArm, CenterTorso, ...)
    int x = 0, y = 0, w = 0, h = 0;
    bool contains(int px, int py) const { return px >= x && py >= y && px < x + w && py < y + h; }
};

struct Hardpoint {
    std::string id;         // "<Location>.<Mount>.<n>"
    std::string location;
    Mount mount = Mount::None;
    std::string socket;     // appearance weapon-node name
    unsigned int key = 0;   // hardpointKey(id)
};

struct PackageChassis {
    std::string chassisId;      // qualified, e.g. "bt2018:marauder"
    std::string stem;           // CSV / appearance / object-type name
    std::string fitPath;        // absolute path of the chassisdef.fit (object type source)
    std::string modId;
    std::string balanceProfile;
    std::string hudIcon;        // P6: HUD strip base (<base>_<W>x<H>.tga in data/art), empty = stock atlas
    long objTypeNum = -1;       // runtime allocation; never saved (saves carry chassisId)
    float scale = 1.0f, tonnage = 0.0f, emptyMass = 0.0f, payload = 0.0f;
    bool purchasable = false;
    int layoutRev = 1;          // pack-declared layout revision (LayoutRev); saves/exports of a revised layout are fenced from older builds
    std::vector<Region> regions;
    std::vector<Hardpoint> hardpoints;
    std::vector<int> antiPersonnelOrdinals;   // component ordinals that may use AntiPersonnel mounts

    const Hardpoint* hardpointByKey(unsigned int key) const {
        for (const Hardpoint& h : hardpoints) if (h.key == key) return &h;
        return nullptr;
    }
    const Hardpoint* hardpointById(std::string_view id) const { return hardpointByKey(hardpointKey(id)); }
    bool apCapable(int ordinal) const {
        for (int o : antiPersonnelOrdinals) if (o == ordinal) return true;
        return false;
    }
};

// Region wholly containing the w x h footprint at (x, y); nullptr when it straddles
// regions or leaves the grid.
inline const Region* regionForFootprint(const PackageChassis& c, int x, int y, int w, int h) {
    for (const Region& r : c.regions)
        if (r.contains(x, y) && r.contains(x + w - 1, y + h - 1)) return &r;
    return nullptr;
}

// One installed grid item as the legality rules see it.
struct Placed {
    int x = -1, y = -1, w = 1, h = 1;
    Mount category = Mount::None;   // weapon's own mount class; None for non-weapons
    int ordinal = -1;               // component ordinal (AntiPersonnel capability lookup)
    float weight = 0.0f;
};

// Assign every weapon a free mount in the region it sits in. Non-AP weapons take a mount
// of their own category; AP-capable weapons prefer an AntiPersonnel mount, then their
// category's. Deterministic: items are processed in the order given. Result[i] is the
// hardpoint index for items[i], or -1 (non-weapon, or no free mount -> illegal).
inline std::vector<int> assignMounts(const PackageChassis& c, const std::vector<Placed>& items,
                                     bool* allMounted = nullptr) {
    std::vector<int> out(items.size(), -1);
    std::vector<bool> used(c.hardpoints.size(), false);
    bool ok = true;
    auto take = [&](std::string_view loc, Mount m) -> std::optional<int> {
        for (size_t k = 0; k < c.hardpoints.size(); ++k)
            if (!used[k] && c.hardpoints[k].mount == m && c.hardpoints[k].location == loc) {
                used[k] = true;
                return static_cast<int>(k);
            }
        return std::nullopt;
    };
    // Pass 1: non-AP weapons claim category mounts first so an AP-capable item never
    // steals the only Energy mount a laser needs.
    for (int pass = 0; pass < 2; ++pass) {
        for (size_t i = 0; i < items.size(); ++i) {
            const Placed& p = items[i];
            if (p.category == Mount::None) continue;
            const bool ap = c.apCapable(p.ordinal);
            if ((pass == 0) == ap) continue;
            const Region* r = regionForFootprint(c, p.x, p.y, p.w, p.h);
            if (!r) { ok = false; continue; }
            auto k = ap ? take(r->location, Mount::AntiPersonnel) : std::nullopt;
            if (!k) k = take(r->location, p.category);
            if (!k) ok = false;
            out[i] = k.value_or(-1);
        }
    }
    if (allMounted) *allMounted = ok;
    return out;
}

enum class Verdict : int { Legal = 0, OutsideRegion, NoFreeMount, OverPayload };

inline const char* verdictName(Verdict v) {
    switch (v) {
        case Verdict::Legal: return "legal";
        case Verdict::OutsideRegion: return "outside-region";
        case Verdict::NoFreeMount: return "no-free-mount";
        case Verdict::OverPayload: return "over-payload";
    }
    return "?";
}

// The ONE legality rule for adding `cand` to a package chassis that already holds
// `existing` (mech lab drop, variant import, deployment, save load all call this).
// Grid occupancy/heat/sensor rules stay with the legacy caller; this adds what BT
// identity needs: whole-region placement, a free compatible mount, the mass budget.
// A candidate without a grid position (x < 0) is checked for mount availability in ANY
// region that could take it, mirroring the mech lab's auto-place.
inline Verdict checkAdd(const PackageChassis& c, const std::vector<Placed>& existing, const Placed& cand) {
    float mass = cand.weight;
    for (const Placed& p : existing) mass += p.weight;
    if (mass > c.payload + 1e-3f) return Verdict::OverPayload;
    if (cand.x >= 0 && !regionForFootprint(c, cand.x, cand.y, cand.w, cand.h)) return Verdict::OutsideRegion;
    if (cand.category == Mount::None) return Verdict::Legal;
    std::vector<Placed> all = existing;
    if (cand.x >= 0) {
        all.push_back(cand);
        bool ok = false;
        assignMounts(c, all, &ok);
        return ok ? Verdict::Legal : Verdict::NoFreeMount;
    }
    for (const Region& r : c.regions) {
        Placed probe = cand;
        probe.x = r.x; probe.y = r.y;
        if (probe.w > r.w || probe.h > r.h) continue;
        std::vector<Placed> trial = existing;
        trial.push_back(probe);
        bool ok = false;
        assignMounts(c, trial, &ok);
        if (ok) return Verdict::Legal;
    }
    return Verdict::NoFreeMount;
}

// Runtime object-type numbers for package chassis: after every legacy packet and below
// the reserved misc-terrain handles. Order = the (sorted) order of `chassis`; numbers are
// never saved. Returns how many were assigned; the rest keep objTypeNum = -1.
inline size_t allocateTypeNums(std::vector<PackageChassis>& chassis, long firstFree, long limitExclusive) {
    size_t n = 0;
    long next = firstFree < 1 ? 1 : firstFree;
    for (PackageChassis& c : chassis) {
        if (next >= limitExclusive) { c.objTypeNum = -1; continue; }
        c.objTypeNum = next++;
        ++n;
    }
    return n;
}

// Total mass of a placed loadout (the payload side of checkAdd).
inline float massUsed(const std::vector<Placed>& items) {
    float m = 0.0f;
    for (const Placed& p : items) m += p.weight;
    return m;
}

} // namespace mc2pkg

// ---- engine registry (package_chassis_registry.cpp) ----------------------------------
// Builds the registry once per process from the mounted mods; firstFreeTypeNum is the
// Object2.pak packet count. Safe to call repeatedly (first call wins).
void packageChassisEnsureRegistry(long firstFreeTypeNum, long limitExclusive);
const std::vector<mc2pkg::PackageChassis>& packageChassisAll();
const mc2pkg::PackageChassis* packageChassisByTypeNum(long objTypeNum);
const mc2pkg::PackageChassis* packageChassisByStem(std::string_view stem);
const mc2pkg::PackageChassis* packageChassisById(std::string_view chassisId);

#endif // PACKAGE_CHASSIS_H
